public async Task<IReadOnlyList<DocumentChunk>> SearchAuthorizedChunksAsync(
    Guid tenantId,
    IReadOnlyList<string> userSecurityGroups,
    Vector queryEmbedding,
    int topK = 5,
    CancellationToken cancellationToken = default)
{
    // EF Core query translating to SQL with HNSW cosine distance (<=>)
    // Pre-filtering strictly confines traversal to chunks where the tenant matches 
    // AND the chunk's SecurityGroups overlap with the user's validated Entra ID claims.
    return await _dbContext.DocumentChunks
        .AsNoTracking()
        .Where(c => c.TenantId == tenantId)
        .Where(c => c.SecurityGroups.Any(group => userSecurityGroups.Contains(group)))
        .OrderBy(c => c.Embedding.CosineDistance(queryEmbedding))
        .Take(topK)
        .ToListAsync(cancellationToken);
}

[AttributeUsage(AttributeTargets.Method)]
public sealed class ToolPermissionAttribute(ToolRiskLevel riskLevel, string requiredRole) : Attribute
{
    public ToolRiskLevel RiskLevel { get; } = riskLevel;
    public string RequiredRole { get; } = requiredRole;
}

public enum ToolRiskLevel { LowReadOnly, HighImpactMutating }

public sealed class FinancialTools
{
    [ToolPermission(ToolRiskLevel.LowReadOnly, "Finance.Viewer")]
    [Description("Fetches invoice summary by invoice number")]
    public async Task<InvoiceSummary> GetInvoiceAsync(string invoiceId) => ...;

    [ToolPermission(ToolRiskLevel.HighImpactMutating, "Finance.Manager")]
    [Description("Issues a credit memo and triggers payment refund")]
    public async Task<RefundResult> ProcessRefundAsync(string invoiceId, decimal amount)
    {
        // If not running inside an approved human-in-the-loop session, reject execution
        if (!ApprovalContext.Current.IsExplicitlyApprovedByUser)
        {
            throw new HumanApprovalRequiredException(
                actionId: Guid.NewGuid(),
                actionDescription: $"Process refund of ${amount} for invoice {invoiceId}");
        }

        return await _paymentGateway.RefundAsync(invoiceId, amount);
    }
}
